function productCard(p){const v=variantInfo(p),sale=p.old&&p.old>v.price?Math.round((1-v.price/p.old)*100):0;return `<article class="gr16-card gr18-card" data-product-card="${p.id}"><div class="gr16-card-media gr18-card-media"><a href="${url('product.html',{id:p.id})}" aria-label="${esc(p[isAR?'ar':'en'])}"><img src="${p.img}" loading="lazy" alt="${esc(p[isAR?'ar':'en'])}" width="520" height="520"></a>${p.badge_ar?`<span class="gr16-badge">${esc(t(p.badge_ar,p.badge_en||p.badge_ar))}</span>`:sale?`<span class="gr16-badge">−${sale}%</span>`:''}<div class="gr16-card-actions gr18-card-actions"><button data-wish="${p.id}" aria-label="${wish.includes(p.id)?t('إزالة من المفضلة','Remove from wishlist'):t('إضافة للمفضلة','Add to wishlist')}" aria-pressed="${wish.includes(p.id)}">${icon('heart')}</button><button data-compare="${p.id}" aria-label="${compare.includes(p.id)?t('إزالة من المقارنة','Remove from compare'):t('إضافة للمقارنة','Add to compare')}" aria-pressed="${compare.includes(p.id)}">⇄</button></div><a class="gr18-card-view" href="${url('product.html',{id:p.id})}">${t('عرض التفاصيل','View details')}</a></div><div class="gr16-card-body gr18-card-body"><div class="gr18-card-topline"><span>${esc(p.brand)}</span><span class="gr18-stock-dot ${p.stock<=0?'sold':p.stock<10?'low':''}">${p.stock<=0?t('غير متوفر','Out of stock'):p.stock<10?t('كمية محدودة','Low stock'):t('متوفر','In stock')}</span></div><span class="gr16-card-type">${esc(t(p.type_ar,p.type_en))}</span><h3><a href="${url('product.html',{id:p.id})}">${esc(p[isAR?'ar':'en'])}</a></h3><div class="gr18-sku">${esc(p.sku)}</div><div class="gr16-price"><strong>${money(v.price)}</strong>${p.old?`<del>${money(p.old)}</del>`:''}</div><button class="gr16-btn ${p.stock>0?'gr16-btn--primary':'gr16-btn--outline'} gr18-add" data-add="${p.id}" ${p.stock<=0?'disabled':''}>${p.stock>0?t('أضف للسلة','Add to cart'):t('غير متوفر','Unavailable')}</button></div></article>`}
function pageHero(kicker,title,copy=''){return `<section class="gr16-pagehero gr18-pagehero"><div class="gr18-pagehero-mark">ROOTS</div><div class="gr16-container"><span class="gr16-kicker">${esc(kicker)}</span><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</div></section>`}
function grid(rows){return `<div class="gr16-product-grid">${rows.map(productCard).join('')}</div>`}
function renderDrawers(){const cb=qs('[data-cart-drawer-body]'),wb=qs('[data-wish-drawer-body]');if(cb){const valid=cart.map(lineData).filter(Boolean);cb.innerHTML=valid.length?valid.map((d,i)=>`<div class="gr16-cart-line" data-line="${i}"><img src="${d.p.img}" alt=""><div><strong>${esc(d.p[isAR?'ar':'en'])}</strong><small>${esc(d.v.label)}</small><div class="gr16-line-actions"><button data-dec aria-label="${t('تقليل الكمية','Decrease quantity')}">−</button><span>${d.qty}</span><button data-inc aria-label="${t('زيادة الكمية','Increase quantity')}">+</button><button class="gr16-linkbtn" data-remove>${t('حذف','Remove')}</button></div></div><b>${money(d.price*d.qty)}</b></div>`).join(''):`<div class="gr16-empty"><strong>${t('السلة فارغة','Your cart is empty')}</strong><a href="${url('collection.html')}">${t('ابدأ التسوق','Start shopping')}</a></div>`;qs('[data-cart-total]').textContent=money(total())}if(wb){const rows=wish.map(product).filter(Boolean);wb.innerHTML=rows.length?rows.map(p=>`<div class="gr16-cart-line"><img src="${p.img}" alt=""><div><a href="${url('product.html',{id:p.id})}"><strong>${esc(p[isAR?'ar':'en'])}</strong></a><small>${money(p.price)}</small></div><button class="gr16-linkbtn" data-wish="${p.id}">${t('إزالة','Remove')}</button></div>`).join(''):`<div class="gr16-empty"><strong>${t('لا توجد منتجات محفوظة','No saved products')}</strong></div>`}}
function home(){const featured=P.filter(p=>p.stock>0).slice(0,6),sale=P.filter(p=>p.old&&p.stock>0).slice(0,4),recentRows=recent.map(product).filter(Boolean).slice(0,4),brands=[...new Set(P.map(p=>p.brand))].slice(0,6);const needs=[['seeds','من البداية','ابدأ زراعة جديدة','Start a new crop'],['fertilizers','للنمو','قوّي النمو والإنتاج','Feed growth & yield'],['pesticides','للحماية','احمِ المحصول','Protect the crop'],['irrigation','للتجهيز','اضبط الري والتجهيز','Set up irrigation']];return `<section class="gr18-hero"><div class="gr18-hero-bg"><img src="assets/golden-roots-hero.webp" alt="${t('زراعة حديثة','Modern agriculture')}" width="1800" height="1000"></div><div class="gr16-container gr18-hero-inner"><div class="gr18-hero-copy"><span class="gr18-eyebrow">GOLDEN ROOTS · UAE</span><h1>${t('من الجذر، لكل مرحلة في الزراعة.','From the root, for every stage of growing.')}</h1><p>${t('بذور، تغذية، حماية محاصيل، ري وتجهيزات — تجربة مرتبة تساعدك توصل للاحتياج الصح أسرع.','Seeds, nutrition, crop protection, irrigation and equipment — one refined experience that gets you to the right need faster.')}</p><div class="gr16-hero-actions"><a class="gr16-btn gr16-btn--gold" href="${url('collection.html')}">${t('استكشف المتجر','Explore the store')}</a><button class="gr16-btn gr18-hero-search" data-search-open>${t('ابحث عن احتياجك','Search your need')} ${icon('search')}</button></div><div class="gr18-hero-stats"><span><b>${Object.keys(C).length}</b>${t('أقسام رئيسية','main categories')}</span><span><b>${P.length}</b>${t('منتج منظم للتصفح','catalog items')}</span><span><b>AR / EN</b>${t('عربي وإنجليزي','Arabic & English')}</span></div></div><div class="gr18-hero-float"><span>${t('من الزراعة للحصاد','FROM PLANTING TO HARVEST')}</span><strong>${t('اختيارات أوضح. طلب أسرع.','Clearer choices. Faster ordering.')}</strong><div>${['بذور','تغذية','حماية','ري'].map((x,i)=>`<i>${isAR?x:['Seeds','Nutrition','Protection','Irrigation'][i]}</i>`).join('')}</div></div></div><a class="gr18-scroll-cue" href="#gr18-needs"><span></span>${t('اكتشف أكثر','Discover more')}</a></section><section class="gr16-section gr18-needs" id="gr18-needs"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">SHOP BY NEED</span><h2>${t('ابدأ من اللي أرضك محتاجاه','Start with what your land needs')}</h2><p>${t('بدل ما تدور وسط كل المنتجات، اختار الهدف الأول وإحنا نوصلك للقسم الأقرب.','Choose the job first, then move straight to the most relevant category.')}</p></div></div><div class="gr18-needs-grid">${needs.map((n,i)=>`<a href="${url('collection.html',{cat:n[0]})}"><span>0${i+1}</span><div><small>${t(n[1],['Start','Growth','Protect','Setup'][i])}</small><h3>${t(n[2],n[3])}</h3></div><b>↗</b></a>`).join('')}</div></div></section><section class="gr16-section gr18-category-story"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">CATEGORIES</span><h2>${t('كل مرحلة لها أدواتها','Every stage has its essentials')}</h2></div><a href="${url('collections.html')}">${t('كل الأقسام','All categories')} →</a></div><div class="gr18-category-mosaic">${Object.entries(C).map(([k,c],i)=>`<a class="gr18-category-tile tile-${i+1}" href="${url('collection.html',{cat:k})}"><img src="${c.img}" loading="lazy" alt="${esc(t(c.ar,c.en))}"><div><span>0${i+1}</span><h3>${esc(t(c.ar,c.en))}</h3><p>${Object.keys(c.subs||{}).length} ${t('تصنيفات فرعية','subcategories')}</p></div></a>`).join('')}</div></div></section><section class="gr16-section gr18-featured"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">CURATED PICKS</span><h2>${t('مختارات مرتبة للبداية','A curated place to start')}</h2><p>${t('مختارات من أقسام مختلفة للوصول السريع لأهم الاحتياجات.','A focused selection across categories for faster discovery.')}</p></div><a href="${url('collection.html')}">${t('عرض كل المنتجات','View all products')} →</a></div>${grid(featured)}</div></section><section class="gr16-section gr18-solution"><div class="gr16-container"><div class="gr18-solution-panel"><div><span class="gr16-kicker">FARM WORKFLOW</span><h2>${t('عندك قائمة طويلة؟ خلّي الطلب أقصر.','Long farm list? Make ordering shorter.')}</h2><p>${t('استخدم الطلب السريع للكميات، أو احفظ قوائم متكررة للمزرعة وترجع لها وقت ما تحتاج.','Use Quick Order for quantities, or save reusable farm lists for repeat needs.')}</p></div><div><a class="gr16-btn gr16-btn--gold" href="${url('quick-order.html')}">${t('فتح الطلب السريع','Open quick order')}</a><a class="gr16-btn gr18-dark-outline" href="${url('saved-lists.html')}">${t('قوائم المزرعة','Farm lists')}</a></div></div></div></section>${sale.length?`<section class="gr16-section gr18-offers"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">CURRENT OFFERS</span><h2>${t('فرص أفضل على احتياجات مختارة','Better value on selected needs')}</h2></div><a href="${url('offers.html')}">${t('كل العروض','All offers')} →</a></div>${grid(sale)}</div></section>`:''}<section class="gr16-section gr18-brands-strip"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">BRANDS</span><h2>${t('تصفح حسب العلامة التجارية','Browse by brand')}</h2></div><a href="${url('brands.html')}">${t('كل العلامات','All brands')} →</a></div><div class="gr18-brand-row">${brands.map(b=>`<a href="${url('collection.html',{brand:b})}"><i>GR</i><span>${esc(b)}</span></a>`).join('')}</div></div></section>${recentRows.length?`<section class="gr16-section gr18-recent"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">RECENTLY VIEWED</span><h2>${t('كمّل من حيث وقفت','Continue where you left off')}</h2></div></div>${grid(recentRows)}</div></section>`:''}<section class="gr18-confidence"><div class="gr16-container"><div><b>01</b><span>${t('بحث أسرع','Faster search')}</span></div><div><b>02</b><span>${t('اختيارات أوضح','Clearer selection')}</span></div><div><b>03</b><span>${t('طلب كميات','Volume ordering')}</span></div><div><b>04</b><span>${t('عربي وإنجليزي','Arabic & English')}</span></div></div></section>`}
function collectionsPage(){return pageHero('CATALOG',t('الأقسام الزراعية','Agricultural Categories'),t('ستة مسارات واضحة للوصول للمنتجات بسرعة.','Six clear paths to the products you need.'))+`<section class="gr16-section"><div class="gr16-container gr17-collections-grid">${Object.entries(C).map(([k,c])=>`<article class="gr17-cat-panel"><a href="${url('collection.html',{cat:k})}"><img src="${c.img}" alt="${esc(t(c.ar,c.en))}"><h2>${esc(t(c.ar,c.en))}</h2></a><nav>${Object.entries(c.subs||{}).map(([sk,v])=>`<a href="${url('collection.html',{cat:k,sub:sk})}">${esc(t(v[0],v[1]))}</a>`).join('')}</nav></article>`).join('')}</div></section>`}
function filterProducts(){let rows=[...P];const cat=params.get('cat')||'',sub=params.get('sub')||'',brand=params.get('brand')||'',stock=params.get('stock')||'',q=params.get('q')||'',min=+params.get('min')||0,max=+params.get('max')||Infinity;if(cat)rows=rows.filter(p=>p.cat===cat);if(sub)rows=rows.filter(p=>p.sub===sub);if(brand)rows=rows.filter(p=>p.brand===brand);if(stock==='in')rows=rows.filter(p=>p.stock>0);if(stock==='low')rows=rows.filter(p=>p.stock>0&&p.stock<10);if(stock==='out')rows=rows.filter(p=>p.stock<=0);if(q)rows=searchProducts(q).filter(p=>rows.includes(p));rows=rows.filter(p=>p.price>=min&&p.price<=max);const sort=params.get('sort')||'featured';if(sort==='price-asc')rows.sort((a,b)=>a.price-b.price);if(sort==='price-desc')rows.sort((a,b)=>b.price-a.price);if(sort==='name')rows.sort((a,b)=>String(a[isAR?'ar':'en']).localeCompare(String(b[isAR?'ar':'en'])));if(sort==='stock')rows.sort((a,b)=>b.stock-a.stock);if(sort==='sale')rows.sort((a,b)=>(b.old?1:0)-(a.old?1:0));return rows}
function collectionPage(){const rows=filterProducts(),cat=params.get('cat')||'',sub=params.get('sub')||'',title=sub&&cat?subName(cat,sub):cat?catName(cat):t('كل المنتجات','All Products');const brands=[...new Set(P.map(p=>p.brand))];return pageHero('SHOP',title,t(`${rows.length} منتج مطابق لاختيارك`,`${rows.length} products match your selection`))+`<section class="gr16-section"><div class="gr16-container"><form class="gr17-filterbar gr19-filterbar" data-filter-form><input class="gr19-filter-search" type="search" name="q" value="${esc(params.get('q')||'')}" placeholder="${t('ابحث داخل النتائج','Search within results')}" aria-label="${t('بحث داخل المنتجات','Search products')}">${sub&&cat?`<input type="hidden" name="sub" value="${esc(sub)}">`:''}<select name="cat" aria-label="${t('القسم','Category')}"><option value="">${t('كل الأقسام','All categories')}</option>${Object.keys(C).map(k=>`<option value="${k}" ${cat===k?'selected':''}>${esc(catName(k))}</option>`).join('')}</select><select name="stock"><option value="">${t('كل حالات التوفر','All availability')}</option><option value="in" ${params.get('stock')==='in'?'selected':''}>${t('متوفر','In stock')}</option><option value="low" ${params.get('stock')==='low'?'selected':''}>${t('كمية محدودة','Low stock')}</option><option value="out" ${params.get('stock')==='out'?'selected':''}>${t('غير متوفر','Out of stock')}</option></select><select name="brand"><option value="">${t('كل البراندات','All brands')}</option>${brands.map(b=>`<option ${params.get('brand')===b?'selected':''}>${esc(b)}</option>`).join('')}</select><div class="gr17-price-filter"><input type="number" name="min" min="0" value="${params.get('min')||''}" placeholder="${t('من','Min')}"><span>—</span><input type="number" name="max" min="0" value="${params.get('max')||''}" placeholder="${t('إلى','Max')}"></div><select name="sort"><option value="featured">${t('مميز','Featured')}</option><option value="price-asc" ${params.get('sort')==='price-asc'?'selected':''}>${t('السعر: الأقل','Price: low')}</option><option value="price-desc" ${params.get('sort')==='price-desc'?'selected':''}>${t('السعر: الأعلى','Price: high')}</option><option value="stock" ${params.get('sort')==='stock'?'selected':''}>${t('الأكثر توفرًا','Most available')}</option><option value="sale" ${params.get('sort')==='sale'?'selected':''}>${t('العروض أولًا','Sales first')}</option></select><button class="gr16-btn gr16-btn--primary">${t('تطبيق','Apply')}</button><a class="gr16-btn gr16-btn--outline" href="${url('collection.html')}">${t('مسح','Reset')}</a></form>${cat?`<div class="gr17-subchips">${Object.entries(C[cat]?.subs||{}).map(([sk,v])=>`<a class="gr16-filter-chip ${sub===sk?'is-active':''}" href="${url('collection.html',{cat,sub:sk,stock:params.get('stock')||'',brand:params.get('brand')||'',min:params.get('min')||'',max:params.get('max')||'',sort:params.get('sort')||'',q:params.get('q')||''})}">${esc(t(v[0],v[1]))}</a>`).join('')}</div>`:''}${rows.length?grid(rows):zeroResults(params.get('q')||title)}</div></section>`}
function zeroResults(q){const alts=P.filter(p=>p.stock>0).slice(0,4);return `<div class="gr16-empty gr17-zero"><h2>${t('مفيش نتيجة مطابقة بالضبط','No exact match found')}</h2><p>${t('جرّب كلمة أقصر أو تصفح المنتجات المقترحة.','Try a shorter term or browse these suggestions.')}</p><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('عرض كل المنتجات','View all products')}</a></div><div class="gr17-zero-suggestions">${grid(alts)}</div>`}
function productPage(){const id=params.get('id'),p=product(id);if(!p)return notFound();recent=[id,...recent.filter(x=>x!==id)].slice(0,12);set(K.recent,recent);const vi=clamp(Math.floor(+params.get('variant')||0),0,Math.max(0,(p.variants?.length||1)-1)),v=variantInfo(p,vi);const specs=isAR?p.specs_ar:p.specs_en;const gallery=[p.img,C[p.cat]?.img,'assets/golden-roots-hero.webp'].filter(Boolean);const recs=P.filter(x=>x.id!==p.id&&x.cat===p.cat&&x.stock>0).slice(0,4),specRows=Object.entries(specs||{});return `<section class="gr16-section gr18-product-section"><div class="gr16-container"><nav class="gr16-breadcrumb"><a href="${url('index.html')}">${t('الرئيسية','Home')}</a><span>›</span><a href="${url('collection.html',{cat:p.cat})}">${catName(p.cat)}</a><span>›</span><span>${esc(p[isAR?'ar':'en'])}</span></nav><div class="gr16-product-layout gr18-product-layout"><div class="gr16-gallery gr18-gallery"><button class="gr17-main-image gr18-main-image" data-gallery-main data-zoom-src="${gallery[0]}"><img class="gr16-main-image" src="${gallery[0]}" alt="${esc(p[isAR?'ar':'en'])}"><span class="gr18-zoom-hint">⌕ ${t('تكبير الصورة','Zoom image')}</span></button><div class="gr16-thumbs gr18-thumbs">${gallery.map((im,i)=>`<button class="gr16-thumb ${i===0?'is-active':''}" data-thumb="${im}" aria-label="${t('صورة المنتج','Product image')} ${i+1}"><img src="${im}" alt=""></button>`).join('')}</div></div><div class="gr16-product-copy gr18-purchase-panel"><div class="gr18-product-head"><span class="gr16-kicker">${esc(t(p.type_ar,p.type_en))}</span><div class="gr18-product-mini-actions"><button data-wish="${p.id}" aria-label="${t('المفضلة','Wishlist')}">${icon('heart')}</button><button data-compare="${p.id}" aria-label="${t('مقارنة','Compare')}">⇄</button></div></div><h1>${esc(p[isAR?'ar':'en'])}</h1><div class="gr16-product-meta"><span>${esc(p.brand)}</span><span>SKU: ${esc(p.sku)}</span><span class="gr16-stock ${p.stock<=0?'sold':''}">${p.stock<=0?t('نفد مؤقتًا','Sold out'):p.stock<10?t(`متبقي ${p.stock} فقط`,`Only ${p.stock} left`):t('متوفر','In stock')}</span></div><div class="gr16-product-price gr18-product-price"><strong data-product-price>${money(v.price)}</strong>${p.old?`<del>${money(p.old)}</del>`:''}</div>${specRows.length?`<div class="gr18-key-specs">${specRows.slice(0,3).map(([k,val])=>`<div><small>${esc(k)}</small><b>${esc(val)}</b></div>`).join('')}</div>`:''}${p.variants?.length?`<label class="gr17-field gr18-field">${t('اختر العبوة / الخيار','Choose pack / option')}<select data-variant>${p.variants.map((x,i)=>`<option value="${i}" ${i===vi?'selected':''}>${esc(t(x[0],x[1]))} — ${money(x[2])}</option>`).join('')}</select></label>`:''}<div class="gr16-buyrow gr18-buyrow"><div class="gr16-qty"><button data-qminus aria-label="${t('تقليل','Decrease')}">−</button><input data-qty type="number" min="1" max="${p.stock}" value="1" aria-label="${t('الكمية','Quantity')}"><button data-qplus aria-label="${t('زيادة','Increase')}">+</button></div><button class="gr16-btn gr16-btn--primary" data-product-add="${p.id}" ${p.stock<=0?'disabled':''}>${p.stock>0?t('أضف للسلة','Add to cart'):t('غير متوفر','Unavailable')}</button></div><div class="gr18-secondary-actions"><button data-list-dialog="${p.id}">＋ ${t('إضافة لقائمة مزرعة','Add to farm list')}</button><a href="${url('quick-order.html')}">${t('طلب كميات','Volume order')} ↗</a></div>${specRows.length?`<details class="gr18-spec-details" open><summary>${t('مواصفات المنتج','Product specifications')}</summary><div class="gr16-specs">${specRows.map(([k,val])=>`<div class="gr16-spec"><span>${esc(k)}</span><b>${esc(val)}</b></div>`).join('')}</div></details>`:''}</div></div></div></section><div class="gr18-mobile-buy"><div><small>${esc(p[isAR?'ar':'en'])}</small><strong data-product-price-mobile>${money(v.price)}</strong></div><button class="gr16-btn gr16-btn--primary" data-product-add="${p.id}" ${p.stock<=0?'disabled':''}>${p.stock>0?t('أضف للسلة','Add to cart'):t('غير متوفر','Unavailable')}</button></div>${recs.length?`<section class="gr16-section gr18-related"><div class="gr16-container"><div class="gr16-head gr18-head"><div><span class="gr16-kicker">YOU MAY ALSO LIKE</span><h2>${t('اختيارات من نفس القسم','More from this category')}</h2></div></div>${grid(recs)}</div></section>`:''}`}
